require_once __DIR__ . '/i18n-extra.php';

function siteStartI18n(): string
{
    $supported = ['en', 'pt', 'es', 'pl'];
    $requested = $_GET['lang'] ?? null;
    $stored = $_SESSION['site_language'] ?? ($_COOKIE['antigas_site_language'] ?? 'en');
    $language = is_string($requested) && in_array($requested, $supported, true)
        ? $requested
        : (is_string($stored) && in_array($stored, $supported, true) ? $stored : 'en');

    if (session_status() === PHP_SESSION_ACTIVE) {
        $_SESSION['site_language'] = $language;
    }
    if (is_string($requested) && in_array($requested, $supported, true)) {
        $secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');
        setcookie('antigas_site_language', $language, [
            'expires' => time() + 31536000,
            'path' => '/',
            'secure' => $secure,
            'httponly' => true,
            'samesite' => 'Lax',
        ]);
    }
    $GLOBALS['antigasLanguage'] = $language;
    return $language;
}

function siteLanguageTag(): string
{
    return ['en' => 'en', 'pt' => 'pt-BR', 'es' => 'es', 'pl' => 'pl'][$GLOBALS['antigasLanguage'] ?? 'en'];
}

function siteTranslation(string $source, array $variables = []): string
{
    $language = $GLOBALS['antigasLanguage'] ?? 'en';
    $text = ANTIGAS_TRANSLATIONS[$language][$source] ?? ANTIGAS_EXTRA_TRANSLATIONS[$language][$source] ?? $source;
    foreach ($variables as $name => $value) {
        $text = str_replace('{' . $name . '}', (string)$value, $text);
    }
    return $text;
}

function siteT(string $source, array $variables = []): string
{
    return htmlspecialchars(siteTranslation($source, $variables), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

function siteTHtml(string $source): string
{
    return strip_tags(siteTranslation($source), '<strong><em><br><code>');
}

function siteLanguageUrl(string $language): string
{
    $path = parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH);
    $path = is_string($path) && $path !== '' ? $path : '/';
    $query = [];
    if (isset($_GET['order']) && is_string($_GET['order']) && preg_match('/\A[a-f0-9]{32}\z/D', $_GET['order'])) {
        $query['order'] = $_GET['order'];
    }
    $query['lang'] = $language;
    return $path . '?' . http_build_query($query, '', '&', PHP_QUERY_RFC3986);
}

function siteLanguageSwitcher(): string
{
    $language = $GLOBALS['antigasLanguage'] ?? 'en';
    $choices = [
        'en' => ['flag' => '🇬🇧', 'code' => 'EN', 'name' => 'English', 'locale' => 'en'],
        'pt' => ['flag' => '🇧🇷', 'code' => 'PT', 'name' => 'Português', 'locale' => 'pt-BR'],
        'es' => ['flag' => '🇪🇸', 'code' => 'ES', 'name' => 'Español', 'locale' => 'es'],
        'pl' => ['flag' => '🇵🇱', 'code' => 'PL', 'name' => 'Polski', 'locale' => 'pl'],
    ];
    $html = '<nav class="language-switcher" aria-label="' . siteT('Choose language') . '"><span class="language-label">' . siteT('Language') . '</span>';
    foreach ($choices as $code => $choice) {
        $current = $code === $language;
        $html .= '<a href="' . htmlspecialchars(siteLanguageUrl($code), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '" lang="' . $choice['locale'] . '" hreflang="' . $code . '" aria-label="' . htmlspecialchars($choice['name'], ENT_QUOTES, 'UTF-8') . '" title="' . htmlspecialchars($choice['name'], ENT_QUOTES, 'UTF-8') . '"' . ($current ? ' aria-current="true"' : '') . '><span class="language-flag" aria-hidden="true">' . $choice['flag'] . '</span><span class="language-code">' . $choice['code'] . '</span></a>';
    }
    return $html . '</nav>';
}
